package alternate;import java.util.*;public class Variant {public Map<String,Integer> apply(String text){var counts=new HashMap<String,Integer>();var word=new StringBuilder();for(int i=0;i<=text.length();i++){char c=i<text.length()?text.charAt(i):' ';if(c>='A'&&c<='Z'||c>='a'&&c<='z')word.append(c);else if(!word.isEmpty()){String key=word.toString();counts.put(key,counts.getOrDefault(key,0)+1);word.setLength(0);}}return counts;}}
